#!/bin/bash
# One-time switch from the 178 old migration files to the 13 feature files.
# Run this BEFORE any plain `supabase db push` on a database created before the switch.
#
# Run from the repo root on a machine signed in to the Supabase CLI and linked
# to the live project (npx supabase link). It changes the live database's
# migration history only; no schema change is run by the repair step.
#
#   1. Pushes any old migration live hasn't run yet (the old files are put
#      back in supabase/migrations for this step only).
#   2. Marks the 178 old versions as reverted and the 13 feature files as
#      applied, so "db push" treats them as already done.
#   3. Pushes anything written after the switch (20261118000014 onwards) and
#      shows the migration list: local and remote should now match.
#
# Safe to stop at any prompt. Re-running after it finished does nothing harmful.
set -euo pipefail
cd "$(dirname "$0")/.."

OLD_DIR=docs/archive/supabase-migrations/migrations_2026
NEW_DIR=supabase/migrations
OLD_VERSIONS="20260301000000 20260301000001 20260301000002 20260301000003 20260301000004 20260301000005 20260301000006 20260301000007 20260301000008 20260301000009 20260301000010 20260301000011 20260301000012 20260301000013 20260301000014 20260301000015 20260301000016 20260301000017 20260301000020 20260301000021 20260301000022 20260301000024 20260301000025 20260301000026 20260301000027 20260301000028 20260301000029 20260301000032 20260301000033 20260301000034 20260301000035 20260301000036 20260301000037 20260301000039 20260301000040 20260301000042 20260301000043 20260301000044 20260301000045 20260301000046 20260301000047 20260301000048 20260301000049 20260301000050 20260301000051 20260301000052 20260301000053 20260301000054 20260301000055 20260515000056 20260515000057 20260515000058 20260515000059 20260515000060 20260515000061 20260515000062 20260515000063 20260515000064 20260515000065 20260518000001 20260518000066 20260518000067 20260518000068 20260518000069 20260520000070 20260520000071 20260701000072 20260701000073 20260701000074 20260701000075 20260701000076 20260701000077 20260701000078 20260710000100 20260710000101 20260710000102 20260710000103 20260710000104 20260710000105 20260710000106 20260710000107 20260710000108 20260710000109 20260710000150 20260722000001 20260722000002 20260722000003 20260722000004 20260722000005 20260723000001 20260723000002 20260723000003 20260723000004 20260804000001 20260809000001 20260809000002 20260809000003 20260809000004 20260809000005 20260809000006 20260809000007 20260809000008 20260809000009 20260810000001 20260810000002 20260810000003 20260810000004 20260811000001 20260811000002 20260811000003 20260811000004 20261106000001 20261106000002 20261106000003 20261106000005 20261106000006 20261106000007 20261106064242 20261111000001 20261112000001 20261112000002 20261112000003 20261112000004 20261113000001 20261113000002 20261113000003 20261113000004 20261113000005 20261113000006 20261113000007 20261113000008 20261113000009 20261113000010 20261113000011 20261113000012 20261113000013 20261113000014 20261113000015 20261113000016 20261113000017 20261113000018 20261114000001 20261114000002 20261114000003 20261114000004 20261115000001 20261115000010 20261115000011 20261115000012 20261115000013 20261115000014 20261115000015 20261115000016 20261115000017 20261115000018 20261115000019 20261115000020 20261115000021 20261115000022 20261115000023 20261115000024 20261115000025 20261115000026 20261115000027 20261116000001 20261116000002 20261117000001 20261117000002 20261117000003 20261117000004 20261117000005 20261117000006 20261117000007 20261117000008 20261117000009 20261117000010 20261117000011 20261117000012 "
NEW_VERSIONS="20261118000001 20261118000002 20261118000003 20261118000004 20261118000005 20261118000006 20261118000007 20261118000008 20261118000009 20261118000010 20261118000011 20261118000012 20261118000013 "

[ -d "$OLD_DIR" ] || { echo "Missing $OLD_DIR"; exit 1; }
[ "$(ls $OLD_DIR/*.sql | wc -l | tr -d ' ')" = "178" ] || { echo "Expected 178 old files in $OLD_DIR"; exit 1; }
for v in $NEW_VERSIONS; do ls $NEW_DIR/${v}_*.sql >/dev/null 2>&1 || { echo "Missing feature file $v in $NEW_DIR"; exit 1; }; done

echo "Step 1 of 3: bring live up to date with the old files"
STASH=$(mktemp -d)
mv $NEW_DIR/*.sql "$STASH"/
cp $OLD_DIR/*.sql $NEW_DIR/
restore() { rm -f $NEW_DIR/*.sql; mv "$STASH"/*.sql $NEW_DIR/; rmdir "$STASH"; }
trap restore EXIT
npx supabase db push
restore; trap - EXIT

echo "Step 2 of 3: record the switch in live's migration history"
npx supabase migration repair --status reverted $OLD_VERSIONS
npx supabase migration repair --status applied $NEW_VERSIONS

echo "Step 3 of 3: push migrations written after the switch, then check"
npx supabase db push
npx supabase migration list
echo "Done. From now on, new migrations go in supabase/migrations as usual."
